// Defaults applied by Service.normalize for zero fields. HeadChunk is the D-4
// locked 600 s first chunk; TokenTTL is the D-6 locked 4 h; SegmentTime is the
// fMP4-HLS target segment length; PackTimeout bounds one ffmpeg invocation
// (the enrich lane renews its lease across long runs, so the bound is a hang
// guard, not a progress budget).
const (
	defaultHeadChunk   = 600 * time.Second
	defaultTokenTTL    = 4 * time.Hour
	defaultSegmentTime = 4 * time.Second
	defaultPackTimeout = 2 * time.Hour
	defaultFFmpeg      = "ffmpeg"
)

// mediaPrefix is the HTTP mount path of the playback surface (Interface 3:
// web.Options mounts the Service before the SPA fallback at exactly this
// prefix). Artifact pointer URLs persisted in a document's "streams" namespace
// are relative to the server root and start with it.
const mediaPrefix = "/media"

// cookieName / tokenQuery are the two token deliveries (D-6): the cookie is
// primary (browser <video>/hls.js fetches carry it automatically), the query
// parameter is the cookie-less fallback (native clients, cross-origin).
const (
	cookieName = "media_token"
	tokenQuery = "token"
)

// Service is the packaged-playback mechanism: the remux-only pack lane, the
// media-token issuer/verifier, the token-gated /media serving surface, and the
// playback-descriptor projection, in one injectable value (D-3/D-4/D-5/D-6).
// Construct it as a literal; zero-valued knobs fall back to the locked
// defaults (HeadChunk 600s, TokenTTL 4h, SegmentTime 4s, PackTimeout 2h,
// FFmpeg "ffmpeg"). I/O happens ONLY here (pack/serve edges); Describe and
// the arg builders are pure.
//
// Original resolves the direct floor: the item's original file path, read
// from the stored document by the composition root (main wires it over the
// store) — this package never imports a store.
type Service struct {
	// Root is the artifact root inside the server's own data space (never a
	// library directory — the playback surface never writes into libraries).
	Root string
	// Secret is the HMAC media-token secret. It must differ from the admin
	// token (D-6): a media token is a short-lived playback grant, never an
	// API credential.
	Secret []byte
	// Original resolves an item's original file path for the direct floor.
	Original func(ctx context.Context, itemID string) (string, bool)

	TokenTTL    time.Duration             // media token lifetime (default 4h)
	HeadChunk   time.Duration             // head-first first chunk (default 600s)
	SegmentTime time.Duration             // HLS target segment duration (default 4s)
	PackTimeout time.Duration             // per-invocation ffmpeg bound (default 2h)
	FFmpeg      string                    // ffmpeg binary path (default PATH lookup)
	afterHead   func(playlistPath string) // test hook: head published, tail pending
}

// Build is one published packaging run: the artifact pointer (a /media-relative
// playlist URL under the run's build-nonce directory) and the nonce itself.
// A returned build is COMPLETE (its playlist ends with ENDLIST); a head-first
// partial was published transiently mid-Pack and is observable only while the
// run is in flight (INV-head-first).
type Build struct {
	Playlist string `json:"playlist"` // e.g. /media/<itemID>/<nonce>/index.m3u8
	Nonce    string `json:"nonce"`
}

// idCharset guards every path segment resolved from an HTTP request or used to
// build an artifact path: item ids, nonces, and file names may contain only
// these characters, so a traversal cannot reach outside Root (parameterized
// by construction — the same discipline as parameterized SQL).
var idCharset = regexp.MustCompile(`^[A-Za-z0-9._-]+$`)

// normalize fills zero-valued knobs with the locked defaults. Idempotent.
func (s *Service) normalize() {
	if s.TokenTTL <= 0 {
		s.TokenTTL = defaultTokenTTL
	}
	if s.HeadChunk <= 0 {
		s.HeadChunk = defaultHeadChunk
	}
	if s.SegmentTime <= 0 {
		s.SegmentTime = defaultSegmentTime
	}
	if s.PackTimeout <= 0 {
		s.PackTimeout = defaultPackTimeout
	}
	if s.FFmpeg == "" {
		s.FFmpeg = defaultFFmpeg
	}
}

// newNonce returns a fresh 16-hex-char build directory name (D-5: each run
// publishes under a fresh nonce so a repack never collides with a client's
// cached playlist).
func newNonce() (string, error) {
	b := make([]byte, 8)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

// buildDir returns the published directory for one run: Root/<itemID>/<nonce>.
// It errors on any component that could steer the path outside Root.
func (s *Service) buildDir(itemID, nonce string) (string, error) {
	for _, part := range []string{itemID, nonce} {
		if !idCharset.MatchString(part) || part == "." || part == ".." {
			return "", errors.New("stream: unsafe path component")
		}
	}
	return filepath.Join(s.Root, itemID, nonce), nil
}

// ensureRoot creates the artifact root (server data space) on demand.
func (s *Service) ensureRoot() error {
	return os.MkdirAll(s.Root, 0o755)
}
